import sys, os, json, subprocess, tempfile, importlib.util, shutil
sys.path.insert(0, "/tmp/mvharness")
OUT="/home/tirandagan.guest/naive-arm/output"
def load(name, path):
    s=importlib.util.spec_from_file_location(name, path); m=importlib.util.module_from_spec(s); s.loader.exec_module(m); return m
spec = load("mv", f"{OUT}/mv.py").mv_syntax_spec
fails=0
def check(cond, msg):
    global fails
    if not cond: fails+=1; print("FAIL:", msg)
def run(args):
    d=tempfile.mkdtemp(); open(f"{d}/a","w").close(); open(f"{d}/b","w").close(); os.mkdir(f"{d}/dir")
    p=subprocess.run(["/usr/bin/mv",*args], cwd=d, capture_output=True, text=True, stdin=subprocess.DEVNULL)
    shutil.rmtree(d); return p.returncode, p.stderr
def unrecognised(err): return any(s in err for s in ("invalid option","unrecognized option","invalid argument","doesn't allow an argument","requires an argument","ambiguous"))

# 1. every option in spec is accepted by the binary, with the declared value form
seen=set()
for syntax in spec:
    for node in syntax[0]:
        if node.flag in seen: continue
        seen.add(node.flag)
        for sp in [node.flag]+node.alias:
            if sp=="--help" or sp=="--version":
                rc,err=run([sp]); check(rc==0, f"{sp} rc={rc}"); continue
            if node.kind=="Flag":
                rc,err=run([sp,"a","b"]); check(not unrecognised(err), f"flag {sp}: {err.strip()}")
                rc,err=run([sp+"=x","a","b"]) if sp.startswith("--") else (1,"invalid option")
                check(unrecognised(err), f"flag {sp} should reject a value")
            elif node.kind=="Selection":
                for c in node.choices:
                    args=[sp] if c=="" else [sp+"="+c]
                    rc,err=run(args+["a","b"]); check(not unrecognised(err), f"{args}: {err.strip()}")
                rc,err=run([sp+"=zzz","a","b"]); check("invalid argument" in err, f"{sp}=zzz should be rejected")
                # bare form must not consume next word: 'mv --backup a b dir' -> moves a,b into dir, rc 0
                if "" in node.choices:
                    rc,err=run([sp,"a","b","dir"]); check(rc==0 and not err, f"{sp} must not consume following word: {err.strip()}")
            else:  # value option
                for args in ([sp,"val","a","b"], [sp+"=val","a","b"] if sp.startswith("--") else [sp+"val","a","b"]):
                    if node.kind=="Path": args=[a.replace("val","dir") for a in args]
                    rc,err=run(args); check(rc==0 and not err, f"{args}: {err.strip()}")
                rc,err=run([sp]); check("requires an argument" in err, f"{sp} without value should error")
# 2. candidate spellings that must NOT be accepted (not in spec)
declared={s for sy in spec for n in sy[0] for s in [n.flag]+n.alias}
for cand in ["-a","-c","-d","-e","-g","-h","-k","-l","-m","-o","-p","-q","-r","-R","-s","-w","-x","-y","-z","-B","-F","-I","-N","-U","-V","--exchange","--recursive","--target","--dereference","--preserve"]:
    if cand in declared: continue
    rc,err=run([cand,"a","b"]); check(unrecognised(err) or "ambiguous" in err, f"{cand} accepted by binary but not in spec: rc={rc} {err.strip()}")
# short optstring from binary vs spec
short=sorted(s for s in declared if len(s)==2)
check("".join(c.strip("-") for c in short)=="".join(sorted("bfintuvSTZ")), f"short options {short}")
# 3. mv.json consistent with mv.py
j=json.load(open(f"{OUT}/annotation/mv.json"))
jflags={s for e in j["flag"] for s in (e if isinstance(e,list) else [e])}
jopts={s for e in j["option"] for s in e[:-1]}
specflags={s for sy in spec for n in sy[0] if n.kind=="Flag" for s in [n.flag]+n.alias}
specopts={s for sy in spec for n in sy[0] if n.kind!="Flag" for s in [n.flag]+n.alias}
check(jflags==specflags, f"json flags differ: {jflags^specflags}")
check(jopts==specopts, f"json options differ: {jopts^specopts}")
# 4. generators
IO=load("io", f"{OUT}/annotation/InputOutputInfoGeneratorMv.py").InputOutputInfoGeneratorMv
PA=load("pa", f"{OUT}/annotation/ParallelizabilityInfoGeneratorMv.py").ParallelizabilityInfoGeneratorMv
g=IO([],["a","b"]); g.generate_info(); check(g.calls==["all_but_last_operand_is_other_input","only_last_operand_is_other_output"], g.calls)
g=IO(["-t","-v"],["a","b"]); g.generate_info(); check(g.calls==["set_implicit_use_of_stdout","all_operands_are_other_inputs"], g.calls)
p=PA(["-v"],["a","b"]); p.generate_info(); check(p.parallelizers==[], "parallelizers")
print("checks done, failures:", fails)
